from pathlib import Path
import json
R=Path(__file__).resolve().parent
rooms=[('living','Living room','Tailored linen, oak joinery and a honed travertine table.'),('dining','Dining','A six-seat oak table, linen pendants and garden-facing glazing.'),('kitchen','Kitchen','A stone island, integrated appliances and a clear route in from the gallery.'),('bedroom','Primary bedroom','Draped linen bedding, oak headboard and soft bedside lighting.'),('guest','Guest bedroom','A quiet second bedroom with a garden view.'),('study','Study','Open oak bookshelves, a generous desk and daylight.'),('bathroom','Guest bathroom','Wall-supported vanity, ceramic basin and a glass shower enclosure.'),('ensuite','Ensuite','Stone and oak with the vanity placed clear of the garden window.'),('dressing','Dressing room','Open joinery, hanging rails and fitted storage.'),('utility','Utility','Integrated laundry equipment and stone working surfaces.'),('patio','Garden terrace','Outdoor dining and planting connected directly to the living room.')]
for id,_,_ in rooms:
 assert (R/'renders/interiors'/f'{id}.png').exists(),id
cards=''.join(f'<button type="button" data-room="{id}" aria-pressed="{str(i==0).lower()}"><span>{i+1:02}</span>{name}</button>' for i,(id,name,_) in enumerate(rooms))
data=json.dumps([dict(id=id,title=title,description=desc) for id,title,desc in rooms])
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Better Homes — Detailed interior review</title><style>*{box-sizing:border-box}body{margin:0;background:#eeece5;color:#272c26;font:15px/1.6 system-ui}header,main,footer{max-width:1440px;margin:auto;padding:28px 40px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d5d2c7}.brand{letter-spacing:.2em;font-size:12px;font-weight:650}.status{font-size:11px;border:1px solid #929984;border-radius:30px;padding:6px 13px}h1{font:clamp(32px,4.4vw,60px)/1.1 Georgia;margin:22px 0 18px}p{color:#666a60;max-width:720px}.review{display:grid;grid-template-columns:210px minmax(0,1fr);gap:32px;margin-top:32px}nav{display:flex;flex-direction:column;gap:4px}button{font:inherit;text-align:left;border:0;background:none;padding:11px 14px;border-radius:4px;cursor:pointer;color:#555d50}button span{font-size:11px;opacity:.55;display:inline-block;width:30px}button[aria-pressed=true]{background:#394537;color:#fff}button:hover{background:#dce0d4}button[aria-pressed=true]:hover{background:#394537}figure{margin:0}figure img{width:100%;display:block;border-radius:5px;aspect-ratio:14/9;object-fit:cover;background:#e0ded4}figcaption{display:flex;align-items:start;justify-content:space-between;margin-top:16px;gap:18px}h2{font:29px Georgia;margin:0 0 8px}figcaption p{margin:0}.arrows{display:flex;gap:8px;white-space:nowrap}.arrows button{border:1px solid #b8bdad}.note{border-top:1px solid #cdd1c2;padding-top:18px;font-size:13px;margin-top:32px}a{color:#43513d}details{margin-top:24px}summary{cursor:pointer;padding:14px 0}details img{max-width:100%;display:block}footer{font-size:12px;color:#707568;padding-bottom:40px}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.checks figcaption{font-size:12px}@media(max-width:800px){header,main,footer{padding:22px 18px}.review{grid-template-columns:1fr;gap:18px}nav{flex-direction:row;overflow:auto}nav button{white-space:nowrap}.status{max-width:155px;text-align:center}.checks{grid-template-columns:1fr 1fr}figcaption{display:block}.arrows{margin-top:15px}}</style></head><body><header><div class="brand">BETTER HOMES / RESIDENCE 01</div><div class="status">DETAILED BLENDER REVIEW</div></header><main><h1>Warm materials.<br>Room to feel at home.</h1><p>The approved layout, developed into a detailed Blender interior. Explore the rendered room views below. These are authored scene renders; the live website walkthrough is the next stage.</p><div class="review"><nav aria-label="Choose a room">'''+cards+'''</nav><section aria-label="Selected room"><figure><img id="room-image" src="renders/interiors/living.png" alt="Blender render of the living room"><figcaption><div aria-live="polite"><h2 id="room-title">Living room</h2><p id="room-description">Tailored linen, oak joinery and a honed travertine table.</p></div><div class="arrows"><button id="previous" aria-label="Previous room">← Previous</button><button id="next" aria-label="Next room">Next →</button></div></figcaption></figure></section></div><p class="note">Layout and material direction approved. Detailed interior review pending. The editable Blender source includes the original texture maps, fixture lights and cameras. Browser materials, performance and the moving walkthrough still require export and runtime verification.</p><details><summary>Layout and room relationships</summary><img src="plans/lower-room.png" alt="Approved home plan"><p>Detailed furnishing adjustments preserve the approved room layout while clearing the kitchen entrance and moving the ensuite vanity off its window.</p></details><details><summary>Ceiling and wide-angle inspection views</summary><div class="checks">'''
for p in sorted((R/'renders/checks').glob('*.png')):html+=f'<figure><img loading="lazy" src="renders/checks/{p.name}" alt="{p.stem.replace("-"," ")}"><figcaption>{p.stem.replace("-"," ")}</figcaption></figure>'
html+='''</div></details><p><a href="premium-interior.blend">Open the detailed Blender source</a> · <a href="geometry-audit.json">Geometry and route checks</a> · <a href="review.html">Original layout review</a></p></main><footer>Native Blender construction · Original PBR material maps · No paid asset generation</footer><script>const rooms='''+data+''';let selected=0;function show(i){selected=(i+rooms.length)%rooms.length;const r=rooms[selected];document.getElementById('room-image').src='renders/interiors/'+r.id+'.png';document.getElementById('room-image').alt='Blender interior render: '+r.title;document.getElementById('room-title').textContent=r.title;document.getElementById('room-description').textContent=r.description;document.querySelectorAll('[data-room]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.room===r.id)));}document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>show(rooms.findIndex(r=>r.id===b.dataset.room))));document.getElementById('previous').addEventListener('click',()=>show(selected-1));document.getElementById('next').addEventListener('click',()=>show(selected+1));</script></body></html>'''
(R/'interior-review.html').write_text(html)
print('Wrote interior-review.html')
